target.css:
:root {
  --ink: #25382f;
  --muted: #66746b;
  --paper: #fffdf6;
  --moss: #406d52;
  --mint: #dcebdd;
  --lime: #9cc76b;
  --amber: #e9ad4c;
  --coral: #d96e61;
  --line: #d7dfd2;
  --violet: #75669b;
}

.spore-card {
  box-sizing: border-box;
  width: 500px;
  padding: 14px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--moss);
  border-radius: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.title-group {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow {
  margin: 0;
  color: var(--moss);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.topbar h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.7px;
}

.stamp {
  box-sizing: border-box;
  min-width: 52px;
  margin: 0;
  padding: 4px 7px;
  color: var(--violet);
  background: var(--mint);
  border-radius: 8px;
  font-size: 9px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: 0.7px;
  text-align: center;
}

.stamp strong {
  font-size: 13px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin-bottom: 9px;
}

.metric {
  min-height: 62px;
  padding: 8px 9px;
  border-radius: 10px;
}

.temp { background: var(--mint); }
.humid { background: #f7efd9; }
.growth { background: #f7e2df; }

.metric-label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.65px;
}

.metric strong {
  display: block;
  font-size: 22px;
  line-height: 0.9;
  letter-spacing: -0.8px;
}

.metric strong span {
  margin-left: 2px;
  font-size: 12px;
  letter-spacing: 0;
}

.metric small {
  display: block;
  margin-top: 5px;
  color: var(--muted);
  font-size: 10px;
}

.lower-grid {
  display: grid;
  grid-template-columns: 1.45fr 1fr;
  gap: 8px;
  margin-bottom: 9px;
}

.culture-status,
.chamber-note {
  box-sizing: border-box;
  min-height: 76px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 11px;
}

.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.section-heading h2,
.chamber-note h2 {
  margin: 0;
  font-size: 13px;
  line-height: 1.1;
}

.live-dot {
  padding: 3px 5px;
  color: var(--moss);
  background: var(--mint);
  border-radius: 999px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.growth-track {
  height: 7px;
  margin: 12px 0 5px;
  overflow: hidden;
  background: var(--line);
  border-radius: 999px;
}

.track-fill {
  display: block;
  width: 72%;
  height: 100%;
  background: var(--lime);
  border-radius: inherit;
}

.track-labels {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 9px;
}

.track-labels strong {
  color: var(--moss);
}

.chamber-note {
  display: flex;
  align-items: center;
  gap: 9px;
  background: var(--violet);
  border-color: var(--violet);
  color: var(--paper);
}

.note-icon {
  display: grid;
  width: 27px;
  height: 27px;
  place-items: center;
  flex: 0 0 auto;
  color: var(--violet);
  background: var(--amber);
  border-radius: 50%;
  font-size: 16px;
}

.chamber-note h2 {
  color: var(--paper);
}

.chamber-note p {
  margin: 5px 0 0;
  color: var(--mint);
  font-size: 10px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}

.sample-dot {
  width: 7px;
  height: 7px;
  background: var(--coral);
  border-radius: 50%;
}

.card-footer button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--moss);
  border: 0;
  border-radius: 7px;
  font-size: 10px;
  font-weight: 800;
}

